const categoryOrder = ["inicio", "musica", "economia", "rpg", "expresiones", "utilidades", "admin"];
export function catalogPanel(selected = 'inicio') {
    const key = selected in categories ? selected : 'inicio';
    const category = categories[key];
    const helpAddition = key === 'economia'
        ? '\n\n## Más acciones\n• `a!renunciar [oficio]` · dejar un trabajo y conservar nivel y XP; con dos trabajos, indica cuál.\n• `a!gallo nombre NOMBRE` · ponerle nombre a tu gallo.'
        : key === 'rpg'
            ? '\n\n## Liberar mascota\n• `a!liberar` · ver qué se reinicia.\n• `a!liberar confirmar` · liberar la mascota y abrir la incubadora; la mochila y la bitácora se conservan.'
            : '';
    const container = new ContainerBuilder().setAccentColor(0x8b75dc)
        .addTextDisplayComponents(new TextDisplayBuilder().setContent(`${category.body}${helpAddition}`))
        .addActionRowComponents(new ActionRowBuilder().addComponents(new StringSelectMenuBuilder().setCustomId('catalog:category').setPlaceholder('📚 Elegir categoría').setOptions(...categoryOrder.map((value) => {
        const entry = categories[value];
        return { label: entry.label, description: entry.description, value, emoji: entry.emoji, default: value === key };
    }))));
    return { components: [container], flags: ['IsComponentsV2'] };
}
